SELECT
    r.RESV_NUM          AS resvNum,
    m.USER_NICKNAME     AS userNickname,
    r.RESV_STATUS       AS resvStatus,
    rm.ROOM_NAME        AS roomName,
    p.PLAN_NAME         AS planName,
    rr.RESV_CHECK_IN    AS resvCheckIn,
    rr.RESV_CHECK_OUT   AS resvCheckOut,
    r.RESV_PEOPLE       AS resvPeople,
    r.RESV_PRICE        AS resvPrice
FROM RESERVATION r
JOIN MEMBER m ON m.USER_MAIL = r.USER_MAIL
LEFT JOIN ROOM_RESERVATION rr
    ON rr.RESV_NUM = r.RESV_NUM
    AND rr.ROOM_RESV_NUM = (
        SELECT MIN(rr2.ROOM_RESV_NUM)
        FROM ROOM_RESERVATION rr2
        WHERE rr2.RESV_NUM = r.RESV_NUM
    )
LEFT JOIN ROOM rm ON rm.ROOM_IDX = rr.ROOM_IDX
LEFT JOIN PLAN p ON p.PLAN_IDX = rr.PLAN_IDX


        r.ADMIN_IDX = #{adminIdx}


        AND EXISTS (
            SELECT 1 FROM ROOM_RESERVATION rr3
            WHERE rr3.RESV_NUM = r.RESV_NUM
              AND TRUNC(rr3.RESV_CHECK_IN) = #{checkInDate}
        )



        AND (
            UPPER(m.USER_NICKNAME) LIKE #{kw}
            OR UPPER(r.USER_MAIL) LIKE #{kw}
            OR UPPER(m.USER_FIRST_NAME_EN || ' ' || m.USER_LAST_NAME_EN) LIKE #{kw}
            OR UPPER(m.USER_LAST_NAME_EN || ' ' || m.USER_FIRST_NAME_EN) LIKE #{kw}
            OR (m.USER_LAST_NAME_JP || m.USER_FIRST_NAME_JP) LIKE #{kw}
            OR UPPER(r.RESV_MAIL) LIKE #{kw}
            OR UPPER(r.RESV_FIRST_NAME_EN || ' ' || r.RESV_LAST_NAME_EN) LIKE #{kw}
            OR UPPER(r.RESV_LAST_NAME_EN || ' ' || r.RESV_FIRST_NAME_EN) LIKE #{kw}
            OR (r.RESV_LAST_NAME_JP || r.RESV_FIRST_NAME_JP) LIKE #{kw}
        )


ORDER BY r.RESV_NUM DESC

