UPDATE RESERVATION
SET RESV_STATUS = #{status}, RESV_PAY_STATUS = #{payStatus}
WHERE RESV_NUM = #{resvNum} AND ADMIN_IDX = #{adminIdx}

UPDATE ROOM_RESERVATION
SET RESV_STATUS = #{status}, RESV_PAY_STATUS = #{payStatus}
WHERE RESV_NUM = #{resvNum} AND ADMIN_IDX = #{adminIdx}

UPDATE ONSEN_RESERVATION
SET ONSEN_STATUS = #{status}
WHERE RESV_NUM = #{resvNum} AND ADMIN_IDX = #{adminIdx}
